import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import AMapLoader from "@amap/amap-jsapi-loader";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import {
  fetchAnalysis,
  fetchDataRange,
  fetchDirectionRoutes,
  fetchPrediction,
  fetchPredictionCompare,
  fetchPredictionMeta,
  fetchPredictionOptions,
  fetchPublicConfig,
  fetchTraffic,
} from "./api/client";
import "./App.css";

const INTERVAL_OPTIONS = [
  { value: "auto", label: "自动" },
  { value: 10, label: "10 分钟" },
  { value: 20, label: "20 分钟" },
  { value: 30, label: "30 分钟" },
  { value: 60, label: "60 分钟" },
  { value: 120, label: "120 分钟" },
];
const DIRECTION_OPTIONS = ["全部方向", "东向西", "西向东", "南向北", "北向南"];
const PIE_COLORS = ["#4a8fff", "#1bb58a", "#f3c145", "#6a7cff", "#ff7d4d"];

function getConfluenceView(intersections) {
  if (!intersections.length) {
    return { center: [106.506145, 29.639573], zoom: 16.8 };
  }
  const lng = intersections.reduce((s, x) => s + x.longitude, 0) / intersections.length;
  const lat = intersections.reduce((s, x) => s + x.latitude, 0) / intersections.length;
  return { center: [lng, lat], zoom: 16.8 };
}

function toApiTime(value) {
  return value ? value.replace("T", " ") : undefined;
}

function toInputTime(dateOrStr) {
  const date = new Date(dateOrStr);
  if (Number.isNaN(date.getTime())) return "";
  const pad = (v) => `${v}`.padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(
    date.getHours()
  )}:${pad(date.getMinutes())}`;
}

function addMinutes(input, minutes) {
  const date = new Date(input);
  return toInputTime(new Date(date.getTime() + minutes * 60000));
}

function formatBucket(ts) {
  const d = new Date(ts);
  return `${`${d.getHours()}`.padStart(2, "0")}:${`${d.getMinutes()}`.padStart(2, "0")}`;
}

function average(values) {
  if (!values.length) return 0;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function chooseAutoInterval(startInput, endInput) {
  const hours = (new Date(endInput).getTime() - new Date(startInput).getTime()) / 3600000;
  if (hours <= 3) return 10;
  if (hours <= 8) return 20;
  if (hours <= 16) return 30;
  if (hours <= 36) return 60;
  return 120;
}

function resolveInterval(mode, start, end) {
  if (mode === "auto") return chooseAutoInterval(start, end);
  return Number(mode);
}

function buildColorThresholds(values) {
  const positive = values.filter((v) => v > 0).sort((a, b) => a - b);
  if (!positive.length) {
    return { low: 10, high: 20 };
  }
  if (positive.length === 1) {
    return { low: positive[0] * 0.55, high: positive[0] * 0.85 };
  }
  const lowIdx = Math.max(0, Math.floor((positive.length - 1) * 0.34));
  const highIdx = Math.max(lowIdx + 1, Math.floor((positive.length - 1) * 0.68));
  return {
    low: positive[lowIdx],
    high: positive[highIdx],
  };
}

function levelColor(value, thresholds) {
  if (value >= thresholds.high) return "#e14d31";
  if (value >= thresholds.low) return "#f2bf47";
  return "#2cb985";
}

function segmentLength(vehicleCount) {
  if (vehicleCount >= 80) return 0.0012;
  if (vehicleCount >= 40) return 0.00088;
  return 0.00055;
}

function pointDistance(a, b) {
  const dx = a.longitude - b.longitude;
  const dy = a.latitude - b.latitude;
  return Math.sqrt(dx * dx + dy * dy);
}

function clipPathByRatio(path, ratio) {
  if (!path?.length) return [];
  if (path.length < 2) return path;
  const clamped = Math.max(0.12, Math.min(1, ratio));
  const total = path.slice(1).reduce((sum, point, idx) => sum + pointDistance(path[idx], point), 0);
  if (!total) return path;
  const target = total * clamped;

  let walked = 0;
  const clipped = [path[0]];
  for (let idx = 1; idx < path.length; idx += 1) {
    const prev = path[idx - 1];
    const curr = path[idx];
    const segment = pointDistance(prev, curr);
    if (walked + segment <= target) {
      clipped.push(curr);
      walked += segment;
      continue;
    }
    const remain = target - walked;
    const t = segment ? remain / segment : 0;
    clipped.push({
      longitude: prev.longitude + (curr.longitude - prev.longitude) * t,
      latitude: prev.latitude + (curr.latitude - prev.latitude) * t,
    });
    break;
  }
  return clipped;
}

function groupDirectionAverages(rows) {
  const grouped = new Map();
  rows.forEach((row) => {
    const key = `${row.site_name}|${row.approach}`;
    const current = grouped.get(key) || { sum: 0, n: 0 };
    current.sum += row.vehicle_count;
    current.n += 1;
    grouped.set(key, current);
  });
  const averages = new Map();
  grouped.forEach((value, key) => {
    averages.set(key, value.n ? value.sum / value.n : 0);
  });
  return averages;
}

function getRoadAverage(rows) {
  const grouped = new Map();
  rows.forEach((row) => {
    const current = grouped.get(row.site_name) || { sum: 0, n: 0 };
    current.sum += row.vehicle_count;
    current.n += 1;
    grouped.set(row.site_name, current);
  });
  const result = new Map();
  grouped.forEach((v, k) => result.set(k, v.n ? v.sum / v.n : 0));
  return result;
}

function buildDirectionData(rows) {
  const grouped = new Map();
  rows.forEach((row) => {
    grouped.set(row.approach, (grouped.get(row.approach) || 0) + row.vehicle_count);
  });
  return [...grouped.entries()].map(([name, value]) => ({ name, value }));
}

function buildTenMinuteHistory(rows) {
  if (!rows.length) return [];
  const grouped = new Map();
  rows.forEach((row) => {
    const ts = new Date(row.timestamp);
    const minute = ts.getMinutes();
    const bucketMinute = minute < 10 ? 0 : Math.floor(minute / 10) * 10;
    ts.setMinutes(bucketMinute, 0, 0);
    const key = ts.toISOString();
    const current = grouped.get(key) || { timestamp: new Date(ts), sum: 0, n: 0 };
    current.sum += Number(row.vehicle_count) || 0;
    current.n += 1;
    grouped.set(key, current);
  });
  return [...grouped.values()]
    .sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime())
    .map((item) => ({
      timestamp: item.timestamp.toISOString(),
      bucketLabel: formatBucket(item.timestamp),
      history_vehicle_count: Math.round(item.sum / item.n),
    }));
}

function mergePredictionSeries(historyRows, predictionRows) {
  const merged = new Map();
  historyRows.forEach((row) => {
    merged.set(row.timestamp, {
      timestamp: row.timestamp,
      bucketLabel: row.bucketLabel,
      history_vehicle_count: row.history_vehicle_count,
    });
  });
  predictionRows.forEach((row) => {
    const key = row.timestamp;
    const current = merged.get(key) || { timestamp: row.timestamp, bucketLabel: row.bucketLabel };
    current.predicted_vehicle_count = row.predicted_vehicle_count;
    merged.set(key, current);
  });
  return [...merged.values()].sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
}

function sleep(ms) {
  return new Promise((resolve) => {
    window.setTimeout(resolve, ms);
  });
}

function cardStats(rows) {
  if (!rows.length) return { flow: 0, speed: 0, weather: { icon: "🌡️", text: "-", detail: "" } };
  const weather = getWeatherSummary(rows);
  return {
    flow: Math.round(rows.reduce((s, x) => s + x.vehicle_count, 0) / rows.length),
    speed: Number((rows.reduce((s, x) => s + x.avg_speed, 0) / rows.length).toFixed(1)),
    weather,
  };
}

function weatherIcon(text) {
  const map = {
    晴: "☀️",
    多云: "⛅",
    阴: "☁️",
    小雨: "🌦️",
    中雨: "🌧️",
    大雨: "🌧️",
    雷阵雨: "⛈️",
    雾: "🌫️",
  };
  return map[text] || "🌡️";
}

function getWeatherSummary(rows) {
  const grouped = new Map();
  rows.forEach((row) => {
    const w = row.weather || "未知";
    grouped.set(w, (grouped.get(w) || 0) + 1);
  });
  const entries = [...grouped.entries()].sort((a, b) => b[1] - a[1]);
  const main = entries[0]?.[0] || "未知";
  const total = entries.reduce((s, [, c]) => s + c, 0) || 1;
  const mainPct = Math.round((entries[0][1] / total) * 100);
  if (entries.length <= 1) {
    return { icon: weatherIcon(main), text: `${main} ${mainPct}%`, detail: "" };
  }
  const secondary = entries[1];
  const secPct = Math.round((secondary[1] / total) * 100);
  return {
    icon: "🌤️",
    text: `${main} ${mainPct}%`,
    detail: `次天气：${secondary[0]} ${secPct}%（共${entries.length}种）`,
  };
}

function App() {
  const [amapKey, setAmapKey] = useState("");
  const [intersections, setIntersections] = useState([]);

  const [startInput, setStartInput] = useState("");
  const [endInput, setEndInput] = useState("");
  const [timeLimit, setTimeLimit] = useState({ min: "", max: "" });
  const [applied, setApplied] = useState(null);
  const [timeCollapsed, setTimeCollapsed] = useState(false);

  const [direction, setDirection] = useState("全部方向");
  const [flowRoad, setFlowRoad] = useState("全部路口平均");
  const [speedRoad, setSpeedRoad] = useState("全部路口平均");
  const [flowIntervalMode, setFlowIntervalMode] = useState("auto");
  const [speedIntervalMode, setSpeedIntervalMode] = useState("auto");

  const [flowData, setFlowData] = useState([]);
  const [speedData, setSpeedData] = useState([]);
  const [highlightRows, setHighlightRows] = useState([]);
  const [directionRoutes, setDirectionRoutes] = useState([]);
  const [predictionRoad, setPredictionRoad] = useState("");
  const [predictionDirection, setPredictionDirection] = useState("北向南");
  const [predictionData, setPredictionData] = useState([]);
  const [predictionHistoryData, setPredictionHistoryData] = useState([]);
  const [predictionMeta, setPredictionMeta] = useState(null);
  const [predictionOptions, setPredictionOptions] = useState([]);
  const [predictionLoading, setPredictionLoading] = useState(false);
  const [predictionEmptyText, setPredictionEmptyText] = useState("当前路口与方向暂无预测数据");
  const [predictionCompare, setPredictionCompare] = useState(null);

  const [popupVisible, setPopupVisible] = useState(false);
  const [popupRoad, setPopupRoad] = useState("");
  const [popupPos, setPopupPos] = useState({ left: 0, top: 0 });
  const [popupRows, setPopupRows] = useState([]);

  const [mainLoading, setMainLoading] = useState(false);
  const [error, setError] = useState("");

  const mapContainerRef = useRef(null);
  const mapRef = useRef(null);
  const AMapRef = useRef(null);
  const linesRef = useRef([]);
  const confluenceViewRef = useRef({ center: [106.506145, 29.639573], zoom: 16.8 });
  const popupCacheRef = useRef(new Map());
  const dragRef = useRef({ dragging: false, dx: 0, dy: 0 });

  const endMin = useMemo(() => {
    if (!startInput) return timeLimit.min;
    return toInputTime(new Date(new Date(startInput).getTime() + 3600000));
  }, [startInput, timeLimit.min]);

  const flowYAxisDomain = useMemo(() => {
    if (!flowData.length) return [0, 10];
    const values = flowData.map((x) => Number(x.vehicle_count) || 0);
    const max = Math.max(...values);
    return [0, Math.max(10, Math.ceil(max * 1.15))];
  }, [flowData]);

  const speedYAxisDomain = useMemo(() => {
    if (!speedData.length) return [0, 10];
    const values = speedData.map((x) => Number(x.avg_speed) || 0);
    const min = Math.min(...values);
    const max = Math.max(...values);
    const low = Math.max(0, Math.floor(min * 0.9));
    const high = Math.max(10, Math.ceil(max * 1.1));
    return [low, high];
  }, [speedData]);

  const openPopup = useCallback((site) => {
    if (!mapRef.current) return;
    const pixel = mapRef.current.lngLatToContainer([site.longitude, site.latitude]);
    const x = typeof pixel.getX === "function" ? pixel.getX() : pixel.x;
    const y = typeof pixel.getY === "function" ? pixel.getY() : pixel.y;
    const left = Math.max(20, Math.min(x + 24, mapContainerRef.current.clientWidth - 340));
    const top = Math.max(88, Math.min(y - 20, mapContainerRef.current.clientHeight - 220));

    setPopupRoad(site.site_name);
    setPredictionRoad(site.site_name);
    if (direction !== "全部方向") {
      setPredictionDirection(direction);
    }
    setPopupRows([]);
    setPopupVisible(true);
    setPopupPos({ left, top });
  }, [direction]);

  useEffect(() => {
    let active = true;
    async function bootstrap() {
      try {
        const [cfg, range, routes] = await Promise.all([
          fetchPublicConfig(),
          fetchDataRange(),
          fetchDirectionRoutes(),
        ]);
        if (!active) return;
        setAmapKey(cfg.amap_api_key);
        const sites = (cfg.intersections || []).filter((x) => x.longitude || x.latitude);
        setIntersections(sites);
        setDirectionRoutes(routes || []);
        if (sites.length) {
          setPredictionRoad((prev) => prev || sites[0].site_name);
        }

        const min = toInputTime(range.min_timestamp);
        const max = toInputTime(range.max_timestamp);
        const predictionReadyStart = addMinutes(min, 288 * 5);
        const start = predictionReadyStart < max ? predictionReadyStart : min;
        const initEnd = toInputTime(new Date(new Date(start).getTime() + 3600000));
        const end = initEnd > max ? max : initEnd;
        setTimeLimit({ min, max });
        setStartInput(start);
        setEndInput(end);
        setApplied({ start, end });
      } catch (err) {
        if (!active) return;
        setError(`初始化失败：${err.message}`);
      }
    }
    bootstrap();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    let active = true;
    async function loadPredictionMeta() {
      try {
        const [meta, options] = await Promise.all([fetchPredictionMeta(), fetchPredictionOptions()]);
        if (!active) return;
        setPredictionMeta(meta);
        setPredictionOptions(options || []);
        if ((options || []).length) {
          setPredictionRoad((prev) => prev || options[0].site_name);
          setPredictionDirection((prev) => prev || options[0].directions?.[0] || "北向南");
        }
      } catch (err) {
        if (!active) return;
        setPredictionMeta(null);
        setPredictionOptions([]);
      }
    }
    loadPredictionMeta();
    return () => {
      active = false;
    };
  }, []);

  const predictionDirectionOptions = useMemo(() => {
    const current = predictionOptions.find((item) => item.site_name === predictionRoad);
    return current?.directions?.length ? current.directions : DIRECTION_OPTIONS.filter((x) => x !== "全部方向");
  }, [predictionOptions, predictionRoad]);

  useEffect(() => {
    if (!predictionDirectionOptions.length) return;
    if (!predictionDirectionOptions.includes(predictionDirection)) {
      setPredictionDirection(predictionDirectionOptions[0]);
    }
  }, [predictionDirection, predictionDirectionOptions]);

  useEffect(() => {
    if (!amapKey || !intersections.length || !mapContainerRef.current) return undefined;
    let destroyed = false;
    async function initMap() {
      try {
        const AMap = await AMapLoader.load({
          key: amapKey,
          version: "2.0",
          plugins: ["AMap.Scale"],
        });
        if (destroyed) return;
        AMapRef.current = AMap;
        const view = getConfluenceView(intersections);
        confluenceViewRef.current = view;
        const map = new AMap.Map(mapContainerRef.current, {
          center: view.center,
          zoom: view.zoom,
          viewMode: "2D",
        });
        map.addControl(new AMap.Scale());
        mapRef.current = map;

        intersections.forEach((site) => {
          const labelOffsetMap = {
            星峰路交叉口: [-34, -25],
            星光大道北延申段: [20, -6],
            星峰路康田路交叉口: [-28, -26],
            恒福路: [10, -24],
          };
          const customLabelOffset = labelOffsetMap[site.site_name] || [0, -24];
          const marker = new AMap.Marker({
            position: [site.longitude, site.latitude],
            content: '<div class="road-dot"></div>',
            label: {
              direction: "top",
              content: `<div class="amap-label">${site.site_name}</div>`,
              offset: new AMap.Pixel(customLabelOffset[0], customLabelOffset[1]),
            },
          });
          marker.on("click", () => openPopup(site));
          marker.setMap(map);
        });
      } catch (err) {
        setError(
          `地图加载失败：${err.message}。请确认 Web JS API key 白名单包含 localhost 和 127.0.0.1。`
        );
      }
    }
    initMap();
    return () => {
      destroyed = true;
      linesRef.current.forEach((x) => x.setMap(null));
      linesRef.current = [];
      if (mapRef.current) mapRef.current.destroy();
      mapRef.current = null;
    };
  }, [amapKey, intersections, openPopup]);

  useEffect(() => {
    if (!applied) return;
    let active = true;
    async function loadMainData() {
      try {
        setMainLoading(true);
        setError("");
        const flowInterval = resolveInterval(flowIntervalMode, applied.start, applied.end);
        const speedInterval = resolveInterval(speedIntervalMode, applied.start, applied.end);
        const common = {
          start_time: toApiTime(applied.start),
          end_time: toApiTime(applied.end),
          direction: direction === "全部方向" ? undefined : direction,
        };

        const [flowResp, speedResp, trafficResp] = await Promise.all([
          fetchAnalysis({
            ...common,
            interval_minutes: flowInterval,
            road_name: flowRoad === "全部路口平均" ? undefined : flowRoad,
          }),
          fetchAnalysis({
            ...common,
            interval_minutes: speedInterval,
            road_name: speedRoad === "全部路口平均" ? undefined : speedRoad,
          }),
          fetchTraffic({ ...common, limit: 5000 }),
        ]);
        if (!active) return;
        setFlowData((flowResp || []).map((x) => ({ ...x, bucketLabel: formatBucket(x.bucket_start) })));
        setSpeedData((speedResp || []).map((x) => ({ ...x, bucketLabel: formatBucket(x.bucket_start) })));
        setHighlightRows(trafficResp || []);
      } catch (err) {
        if (!active) return;
        setError(`数据加载失败：${err.message}`);
      } finally {
        if (active) setMainLoading(false);
      }
    }
    loadMainData();
    return () => {
      active = false;
    };
  }, [applied, direction, flowRoad, speedRoad, flowIntervalMode, speedIntervalMode]);

  useEffect(() => {
    if (!popupVisible || !popupRoad || !applied) return;
    let active = true;
    async function loadPopupData() {
      try {
        const cacheKey = `${popupRoad}|${applied.start}|${applied.end}|${direction}`;
        if (popupCacheRef.current.has(cacheKey)) {
          setPopupRows(popupCacheRef.current.get(cacheKey));
          return;
        }
        const rows = await fetchTraffic({
          road_name: popupRoad,
          start_time: toApiTime(applied.start),
          end_time: toApiTime(applied.end),
          direction: direction === "全部方向" ? undefined : direction,
          limit: 5000,
        });
        if (!active) return;
        const safeRows = rows || [];
        popupCacheRef.current.set(cacheKey, safeRows);
        setPopupRows(safeRows);
      } catch (err) {
        if (!active) return;
        setPopupRows([]);
        setError(`路口数据加载失败：${err.message}`);
      }
    }
    loadPopupData();
    return () => {
      active = false;
    };
  }, [popupVisible, popupRoad, applied, direction]);

  useEffect(() => {
    if (!applied || !predictionRoad || !predictionDirection) return;
    let active = true;
    async function loadPredictionData() {
      if (active) setPredictionLoading(true);
      setPredictionEmptyText("当前路口与方向暂无预测数据");
      try {
        const historyStart = toInputTime(new Date(new Date(applied.end).getTime() - 3600000));
        let rows;
        let historyRows;
        let compareResp;
        try {
          [rows, historyRows, compareResp] = await Promise.all([
            fetchPrediction({
              time_range: toApiTime(applied.end),
              road_name: predictionRoad,
              direction: predictionDirection,
            }),
            fetchTraffic({
              road_name: predictionRoad,
              direction: predictionDirection,
              start_time: toApiTime(historyStart),
              end_time: toApiTime(applied.end),
              limit: 5000,
            }),
            fetchPredictionCompare({
              time_range: toApiTime(applied.end),
              road_name: predictionRoad,
              direction: predictionDirection,
            }),
          ]);
        } catch (err) {
          if (err?.message === "Network Error") {
            await sleep(900);
            [rows, historyRows, compareResp] = await Promise.all([
              fetchPrediction({
                time_range: toApiTime(applied.end),
                road_name: predictionRoad,
                direction: predictionDirection,
              }),
              fetchTraffic({
                road_name: predictionRoad,
                direction: predictionDirection,
                start_time: toApiTime(historyStart),
                end_time: toApiTime(applied.end),
                limit: 5000,
              }),
              fetchPredictionCompare({
                time_range: toApiTime(applied.end),
                road_name: predictionRoad,
                direction: predictionDirection,
              }),
            ]);
          } else {
            throw err;
          }
        }
        if (!active) return;
        setPredictionData((rows || []).map((x) => ({ ...x, bucketLabel: formatBucket(x.timestamp) })));
        setPredictionHistoryData(buildTenMinuteHistory(historyRows || []));
        setPredictionCompare(compareResp || null);
      } catch (err) {
        if (!active) return;
        setPredictionData([]);
        setPredictionHistoryData([]);
        setPredictionCompare(null);
        const detail = err?.response?.data?.detail || "";
        if (detail.includes("no history is available")) {
          setPredictionEmptyText("当前时间点之前历史不足，暂时无法生成预测结果");
          return;
        }
        if (err?.message !== "Network Error") {
          setError(`预测数据加载失败：${err.message}`);
        }
      } finally {
        if (active) setPredictionLoading(false);
      }
    }
    loadPredictionData();
    return () => {
      active = false;
    };
  }, [applied, predictionRoad, predictionDirection]);

  useEffect(() => {
    function onMove(e) {
      if (!dragRef.current.dragging || !mapContainerRef.current) return;
      const rect = mapContainerRef.current.getBoundingClientRect();
      const maxLeft = mapContainerRef.current.clientWidth - 320;
      const maxTop = mapContainerRef.current.clientHeight - 220;
      const left = Math.max(8, Math.min(e.clientX - rect.left - dragRef.current.dx, maxLeft));
      const top = Math.max(68, Math.min(e.clientY - rect.top - dragRef.current.dy, maxTop));
      setPopupPos({ left, top });
    }
    function onUp() {
      dragRef.current.dragging = false;
    }
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    return () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    };
  }, []);

  const roadAvg = useMemo(() => getRoadAverage(highlightRows), [highlightRows]);
  const directionAverages = useMemo(() => groupDirectionAverages(highlightRows), [highlightRows]);
  const predictionYAxisDomain = useMemo(() => {
    const values = [
      ...predictionData.map((x) => Number(x.predicted_vehicle_count) || 0),
      ...predictionHistoryData.map((x) => Number(x.history_vehicle_count) || 0),
    ].filter((v) => Number.isFinite(v));
    if (!values.length) return [0, 10];
    const min = Math.min(...values);
    const max = Math.max(...values);
    const spread = Math.max(1, max - min);
    const padding = Math.max(1, Math.ceil(spread * 0.35));
    const low = Math.max(0, Math.floor(min - padding));
    const high = Math.max(low + 4, Math.ceil(max + padding));
    return [low, high];
  }, [predictionData, predictionHistoryData]);
  const predictionChartData = useMemo(
    () => mergePredictionSeries(predictionHistoryData, predictionData),
    [predictionHistoryData, predictionData]
  );
  const predictionSummary = useMemo(() => {
    if (!predictionData.length) {
      return {
        avg: 0,
        peak: 0,
        low: 0,
        trendText: "当前组合暂无可展示的预测序列。",
      };
    }
    const values = predictionData.map((item) => Number(item.predicted_vehicle_count) || 0);
    const first = values[0];
    const last = values[values.length - 1];
    const delta = last - first;
    let trendText = "未来 1 小时整体保持平稳。";
    if (delta >= 2) trendText = "未来 1 小时预测车流量有上升趋势。";
    if (delta <= -2) trendText = "未来 1 小时预测车流量有回落趋势。";
    return {
      avg: Math.round(average(values)),
      peak: Math.max(...values),
      low: Math.min(...values),
      trendText,
    };
  }, [predictionData]);
  const colorThresholds = useMemo(
    () => buildColorThresholds([...directionAverages.values()]),
    [directionAverages]
  );
  useEffect(() => {
    if (!mapRef.current || !AMapRef.current) return;
    linesRef.current.forEach((x) => x.setMap(null));
    linesRef.current = [];
    const routeMax = Math.max(...directionAverages.values(), 1);

    if (directionRoutes.length) {
      directionRoutes.forEach((route) => {
        const avgCount = directionAverages.get(`${route.site_name}|${route.direction}`) || 0;
        if (avgCount <= 0) return;
        const clipped = clipPathByRatio(route.path, avgCount / routeMax);
        if (clipped.length < 2) return;
        const line = new AMapRef.current.Polyline({
          path: clipped.map((p) => [p.longitude, p.latitude]),
          strokeColor: levelColor(avgCount, colorThresholds),
          strokeWeight: 7,
          strokeOpacity: 0.94,
          lineCap: "round",
          lineJoin: "round",
          showDir: true,
        });
        line.setMap(mapRef.current);
        linesRef.current.push(line);
      });
      return;
    }

    intersections.forEach((site, idx) => {
      const avg = roadAvg.get(site.site_name) || 0;
      const len = segmentLength(avg);
      const horizontal = idx % 2 === 0;
      const p1 = horizontal
        ? [site.longitude - len / 2, site.latitude]
        : [site.longitude, site.latitude - len / 2];
      const p2 = horizontal
        ? [site.longitude + len / 2, site.latitude]
        : [site.longitude, site.latitude + len / 2];
      const line = new AMapRef.current.Polyline({
        path: [p1, p2],
        strokeColor: levelColor(avg, colorThresholds),
        strokeWeight: 8,
        strokeOpacity: 0.92,
        lineCap: "round",
      });
      line.setMap(mapRef.current);
      linesRef.current.push(line);
    });
  }, [roadAvg, intersections, directionRoutes, directionAverages, colorThresholds]);

  const roadOptions = useMemo(
    () => ["全部路口平均", ...intersections.map((x) => x.site_name)],
    [intersections]
  );

  const popupDirectionData = useMemo(() => buildDirectionData(popupRows), [popupRows]);
  const popupStats = useMemo(() => cardStats(popupRows), [popupRows]);

  function handleConfirmTime() {
    if (!startInput || !endInput) {
      setError("请先完整选择时间。");
      return;
    }
    const start = new Date(startInput).getTime();
    const end = new Date(endInput).getTime();
    if (end - start < 3600000) {
      setError("终止时间必须至少晚于起始时间 1 小时。");
      return;
    }
    setApplied({ start: startInput, end: endInput });
  }

  function handleResetView() {
    if (!mapRef.current) return;
    mapRef.current.setCenter(confluenceViewRef.current.center);
    mapRef.current.setZoom(confluenceViewRef.current.zoom);
  }

  function handleZoomIn() {
    if (!mapRef.current) return;
    mapRef.current.setZoom(mapRef.current.getZoom() + 1);
  }

  function handleZoomOut() {
    if (!mapRef.current) return;
    mapRef.current.setZoom(mapRef.current.getZoom() - 1);
  }

  return (
    <div className="app-shell">
      <div className="main-layout">
        <section className="left-map-panel">
          <div className="panel-title">实时流量地图</div>
          <div className={`time-card ${timeCollapsed ? "collapsed" : ""}`}>
            <div className="time-card-header">
              <span className="time-title">起始时间</span>
              <button
                type="button"
                className="collapse-btn"
                title={timeCollapsed ? "展开时间选择器" : "收起时间选择器"}
                onClick={() => setTimeCollapsed((v) => !v)}
              >
                {timeCollapsed ? "›" : "‹"}
              </button>
            </div>
            {!timeCollapsed ? (
              <>
                <input
                  type="datetime-local"
                  min={timeLimit.min}
                  max={timeLimit.max}
                  value={startInput}
                  onChange={(e) => {
                    const v = e.target.value;
                    setStartInput(v);
                    const minEnd = new Date(new Date(v).getTime() + 3600000);
                    if (endInput && new Date(endInput).getTime() < minEnd.getTime()) {
                      setEndInput(toInputTime(minEnd));
                    }
                  }}
                />
                <label>终止时间</label>
                <input
                  type="datetime-local"
                  min={endMin}
                  max={timeLimit.max}
                  value={endInput}
                  onChange={(e) => setEndInput(e.target.value)}
                />
                <button type="button" className="confirm-btn" onClick={handleConfirmTime}>
                  确定
                </button>
              </>
            ) : null}
          </div>

          <div className="map-controls">
            <button type="button" title="放大" onClick={handleZoomIn}>
              +
            </button>
            <button type="button" title="缩小" onClick={handleZoomOut}>
              -
            </button>
            <button type="button" title="恢复默认视图" onClick={handleResetView}>
              ⌂
            </button>
          </div>

          <div className="map-frame" ref={mapContainerRef} />

          {popupVisible ? (
            <div className="road-popup" style={{ left: `${popupPos.left}px`, top: `${popupPos.top}px` }}>
              <button type="button" className="popup-close" onClick={() => setPopupVisible(false)}>
                ×
              </button>
              <div
                className="popup-head draggable"
                onMouseDown={(e) => {
                  if (!mapContainerRef.current) return;
                  dragRef.current.dragging = true;
                  const rect = mapContainerRef.current.getBoundingClientRect();
                  dragRef.current.dx = e.clientX - rect.left - popupPos.left;
                  dragRef.current.dy = e.clientY - rect.top - popupPos.top;
                }}
              >
                <h3>{popupRoad}</h3>
                <span className="weather-badge">
                  <i>{popupStats.weather.icon}</i>
                  <span>{popupStats.weather.text}</span>
                </span>
              </div>
              {popupStats.weather.detail ? <div className="weather-detail">{popupStats.weather.detail}</div> : null}
              <div className="popup-metrics">
                <div>
                  <label>总车流量</label>
                  <strong>{popupStats.flow}</strong>
                </div>
                <div>
                  <label>平均车速</label>
                  <strong>{popupStats.speed} km/h</strong>
                </div>
              </div>
              <div className="popup-body">
                <ResponsiveContainer width="48%" height={136}>
                  <PieChart>
                    <Pie
                      data={popupDirectionData}
                      dataKey="value"
                      nameKey="name"
                      innerRadius={28}
                      outerRadius={52}
                      isAnimationActive
                      animationBegin={0}
                      animationDuration={380}
                      animationEasing="ease-out"
                    >
                      {popupDirectionData.map((item, idx) => (
                        <Cell key={item.name} fill={PIE_COLORS[idx % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
                <div className="dir-list">
                  {popupDirectionData.map((item, idx) => (
                    <div key={item.name} className="dir-item">
                      <span className="dir-dot" style={{ backgroundColor: PIE_COLORS[idx % PIE_COLORS.length] }} />
                      <span>{item.name}</span>
                      <strong>{item.value}</strong>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : null}
        </section>

        <aside className="right-panel">
          <section className="section-block">
            <h2>数据分析展示</h2>
            <div className="toolbar-row">
              <select value={direction} onChange={(e) => setDirection(e.target.value)}>
                {DIRECTION_OPTIONS.map((x) => (
                  <option key={x} value={x}>
                    {x}
                  </option>
                ))}
              </select>
              <span className="range-text">
                {applied ? `${applied.start.replace("T", " ")} ~ ${applied.end.replace("T", " ")}` : "-"}
              </span>
            </div>

            <div className="chart-card">
              <div className="chart-head">
                <h3>车流量柱状图</h3>
                <div className="chart-controls">
                  <select value={flowIntervalMode} onChange={(e) => setFlowIntervalMode(e.target.value)}>
                    {INTERVAL_OPTIONS.map((op) => (
                      <option key={`f-${op.value}`} value={op.value}>
                        {op.label}
                      </option>
                    ))}
                  </select>
                  <select value={flowRoad} onChange={(e) => setFlowRoad(e.target.value)}>
                    {roadOptions.map((name) => (
                      <option key={`fr-${name}`} value={name}>
                        {name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              <ResponsiveContainer width="100%" height={206}>
                <BarChart data={flowData} margin={{ left: -10, right: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" tick={{ fontSize: 10 }} />
                  <YAxis width={44} domain={flowYAxisDomain} tick={{ fontSize: 10 }} />
                  <Tooltip />
                  <Bar dataKey="vehicle_count" fill="#3f89ff" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
              {!mainLoading && !flowData.length ? <div className="chart-empty">当前时间段没有车流量数据</div> : null}
            </div>

            <div className="chart-card">
              <div className="chart-head">
                <h3>车速折线图</h3>
                <div className="chart-controls">
                  <select value={speedIntervalMode} onChange={(e) => setSpeedIntervalMode(e.target.value)}>
                    {INTERVAL_OPTIONS.map((op) => (
                      <option key={`s-${op.value}`} value={op.value}>
                        {op.label}
                      </option>
                    ))}
                  </select>
                  <select value={speedRoad} onChange={(e) => setSpeedRoad(e.target.value)}>
                    {roadOptions.map((name) => (
                      <option key={`sr-${name}`} value={name}>
                        {name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              <ResponsiveContainer width="100%" height={206}>
                <LineChart data={speedData} margin={{ left: -12, right: 6 }}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" tick={{ fontSize: 10 }} />
                  <YAxis width={44} domain={speedYAxisDomain} tick={{ fontSize: 10 }} />
                  <Tooltip />
                  <Line type="monotone" dataKey="avg_speed" stroke="#21b88f" strokeWidth={2.4} dot={false} />
                </LineChart>
              </ResponsiveContainer>
              {!mainLoading && !speedData.length ? <div className="chart-empty">当前时间段没有车速数据</div> : null}
            </div>
          </section>

          <section className="section-block">
            <h2>预测</h2>
            <div className="chart-card prediction-card">
              <div className="chart-head">
                <h3>未来 1 小时车流量预测</h3>
                <div className="chart-controls">
                  <select value={predictionDirection} onChange={(e) => setPredictionDirection(e.target.value)}>
                    {predictionDirectionOptions.map((x) => (
                      <option key={`pd-${x}`} value={x}>
                        {x}
                      </option>
                    ))}
                  </select>
                  <select value={predictionRoad} onChange={(e) => setPredictionRoad(e.target.value)}>
                    {predictionOptions.map((item) => (
                      <option key={`pr-${item.site_name}`} value={item.site_name}>
                        {item.site_name}
                      </option>
                    ))}
                    {!predictionOptions.length && intersections.map((item) => (
                      <option key={`pr-${item.site_name}`} value={item.site_name}>
                        {item.site_name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              <ResponsiveContainer width="100%" height={212}>
                <LineChart data={predictionChartData} margin={{ left: -12, right: 6 }}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" tick={{ fontSize: 10 }} />
                  <YAxis width={44} domain={predictionYAxisDomain} tick={{ fontSize: 10 }} />
                  <Tooltip />
                  <Line
                    type="monotone"
                    dataKey="history_vehicle_count"
                    stroke="#4f8cf7"
                    strokeWidth={2.1}
                    dot={{ r: 2.2, strokeWidth: 0, fill: "#4f8cf7" }}
                  />
                  <Line
                    type="monotone"
                    dataKey="predicted_vehicle_count"
                    stroke="#7a8cff"
                    strokeWidth={2.5}
                    strokeDasharray="5 4"
                    dot={{ r: 2.8, strokeWidth: 0, fill: "#7a8cff" }}
                  />
                </LineChart>
              </ResponsiveContainer>
              {!predictionLoading && !predictionData.length ? <div className="chart-empty">{predictionEmptyText}</div> : null}
              {predictionLoading ? <div className="chart-empty">预测数据更新中...</div> : null}
              <div className="prediction-legend">
                <span><i className="legend-line history" /> 最近 1 小时</span>
                <span><i className="legend-line forecast" /> 未来 1 小时预测</span>
              </div>
              <div className="prediction-metrics">
                <div className="prediction-pill">
                  <label>预测均值</label>
                  <strong>{predictionSummary.avg}</strong>
                </div>
                <div className="prediction-pill">
                  <label>峰值</label>
                  <strong>{predictionSummary.peak}</strong>
                </div>
                <div className="prediction-pill">
                  <label>低值</label>
                  <strong>{predictionSummary.low}</strong>
                </div>
              </div>
              <div className="prediction-summary">{predictionSummary.trendText}</div>
              {predictionCompare?.points?.length ? (
                <div className="prediction-backtest">
                  <div className="prediction-backtest-title">该时间点回看误差</div>
                  <div className="prediction-backtest-grid">
                    <div><label>MAE</label><strong>{predictionCompare.mae}</strong></div>
                    <div><label>RMSE</label><strong>{predictionCompare.rmse}</strong></div>
                    <div><label>MAPE</label><strong>{predictionCompare.mape}%</strong></div>
                  </div>
                </div>
              ) : null}
              <div className="prediction-note">
                {predictionMeta?.status === "ready"
                  ? `当前模型：${predictionMeta.model_type}，测试集 MAE ${predictionMeta.test_mae ?? "-"}，RMSE ${predictionMeta.test_rmse ?? "-"}。未来 1 小时按 10 分钟展示。`
                  : "当前未加载到可用预测模型。"}
              </div>
            </div>
          </section>
        </aside>
      </div>

      {mainLoading ? <div className="floating-tip">数据更新中...</div> : null}
      {error ? <div className="floating-error">{error}</div> : null}
    </div>
  );
}

export default App;
